def generate_inputs(device):
    x = torch.zeros(128, 512, device=device, dtype=torch.float32)
    # Each row has unique non-zero position within each tile
    # This makes tile_a[row] uniquely important for that row's computation
    for i in range(128):
        col_in_tile = i % 32
        # Set non-zero values in multiple tiles to ensure strong signal
        for tile in range(16):
            x[i, tile * 32 + col_in_tile] = 50.0 * (1 if tile % 2 == 0 else -1)
    return [x]
